package com.braseiro.pathfinder2e;

import android.content.ContentValues;
import android.database.sqlite.SQLiteDatabase;
import org.json.JSONArray;
import org.json.JSONObject;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.atomic.AtomicBoolean;

/**
 * Local-table host. It exposes only a player's own hero + shared scene/combat facts
 * over the LAN. No cloud service, account, or internet server is required.
 */
public final class LocalTableServer {
    public static final int DEFAULT_PORT=42731;
    private final AppDb db;private ServerSocket server;private final AtomicBoolean running=new AtomicBoolean(false);private String sessionCode="";private int port=DEFAULT_PORT;
    public LocalTableServer(AppDb database){db=database;AppDb.ensureSixZeroSchema(db.getWritableDatabase());}

    public synchronized JSONObject start(){JSONObject out=new JSONObject();try{if(running.get())return status();sessionCode=String.format(Locale.US,"%06d",100000+new Random(System.nanoTime()).nextInt(900000));port=DEFAULT_PORT;server=new ServerSocket();server.setReuseAddress(true);server.bind(new InetSocketAddress(port));running.set(true);provisionPlayers();persist(true);AppExecutors.io().execute(new Runnable(){public void run(){loop();}});return status();}catch(Exception e){stop();try{out.put("running",false).put("error",String.valueOf(e.getMessage()));}catch(Exception ignored){AppLog.ignored("LocalTableServer","Falha tolerada na camada 6.0.",ignored);}return out;}}
    public synchronized void stop(){running.set(false);try{if(server!=null)server.close();}catch(Exception ignored){AppLog.ignored("LocalTableServer","Falha tolerada na camada 6.0.",ignored);}server=null;persist(false);}
    public boolean isRunning(){return running.get();}
    public JSONObject status(){JSONObject o=new JSONObject();try{o.put("running",running.get()).put("code",sessionCode).put("port",port).put("address",localAddress()).put("url",running.get()?"http://"+localAddress()+":"+port+"/":"").put("players",invitations());}catch(Exception ignored){AppLog.ignored("LocalTableServer","Falha tolerada na camada 6.0.",ignored);}return o;}

    private void provisionPlayers(){String profile=db.getActiveMapProfile();SQLiteDatabase sql=db.getWritableDatabase();sql.delete("local_table_players","world_profile=?",new String[]{profile});for(JSONObject h:db.listActiveCharacters()){String token=randomToken();ContentValues v=new ContentValues();v.put("world_profile",profile);v.put("session_code",sessionCode);v.put("character_id",h.optLong("id"));v.put("character_name",h.optString("name"));v.put("player_name",h.optString("name"));v.put("join_token",token);v.put("permissions_json","{\"own_sheet\":true,\"submit_action\":true,\"shared_scene\":true}");v.put("last_seen",0);v.put("active",1);sql.insert("local_table_players",null,v);}}
    private JSONArray invitations(){JSONArray a=new JSONArray();for(JSONObject p:db.queryList("SELECT * FROM local_table_players WHERE world_profile=? AND active=1 ORDER BY character_name",new String[]{db.getActiveMapProfile()})){JSONObject x=new JSONObject();try{x.put("character_id",p.optLong("character_id")).put("character_name",p.optString("character_name")).put("token",p.optString("join_token")).put("url",running.get()?"http://"+localAddress()+":"+port+"/?token="+p.optString("join_token"):"");}catch(Exception ignored){AppLog.ignored("LocalTableServer","Falha tolerada na camada 6.0.",ignored);}a.put(x);}return a;}
    private void persist(boolean enabled){try{ContentValues v=new ContentValues();v.put("world_profile",db.getActiveMapProfile());v.put("session_code",sessionCode.isEmpty()?"000000":sessionCode);v.put("port",port);v.put("enabled",enabled?1:0);v.put("bind_address",localAddress());v.put("started_at",enabled?System.currentTimeMillis():0);v.put("updated_at",System.currentTimeMillis());db.getWritableDatabase().insertWithOnConflict("local_table_sessions",null,v,SQLiteDatabase.CONFLICT_REPLACE);}catch(Exception ignored){AppLog.ignored("LocalTableServer","Falha tolerada na camada 6.0.",ignored);}}
    private void loop(){while(running.get()){try{final Socket socket=server.accept();AppExecutors.io().execute(new Runnable(){public void run(){handle(socket);}});}catch(Exception e){if(running.get())AppLog.w("LocalTable","Falha ao aceitar cliente local.",e);}}}
    private void handle(Socket socket){try{socket.setSoTimeout(7000);BufferedReader r=new BufferedReader(new InputStreamReader(socket.getInputStream(),StandardCharsets.UTF_8));String request=r.readLine();if(request==null)return;String[] parts=request.split(" ");String method=parts.length>0?parts[0]:"GET",target=parts.length>1?parts[1]:"/";int contentLength=0;String line;while((line=r.readLine())!=null&&!line.isEmpty()){int c=line.indexOf(':');if(c>0&&"content-length".equalsIgnoreCase(line.substring(0,c).trim()))try{contentLength=Integer.parseInt(line.substring(c+1).trim());}catch(Exception ignored){AppLog.ignored("LocalTableServer","Falha tolerada na camada 6.0.",ignored);}}char[] bodyChars=new char[Math.max(0,Math.min(16384,contentLength))];int n=0;while(n<bodyChars.length){int got=r.read(bodyChars,n,bodyChars.length-n);if(got<0)break;n+=got;}String body=new String(bodyChars,0,n);URI uri=new URI("http://local"+target);Map<String,String> q=query(uri.getRawQuery());String token=q.get("token");JSONObject player=player(token);if("/".equals(uri.getPath())){if(player.length()==0){reply(socket,403,"text/html; charset=utf-8",loginPage());return;}touch(player);reply(socket,200,"text/html; charset=utf-8",playerPage(player,token));return;}if("/state".equals(uri.getPath())){if(player.length()==0){json(socket,403,new JSONObject().put("error","convite inválido"));return;}touch(player);json(socket,200,playerState(player));return;}if("/action".equals(uri.getPath())&&"POST".equalsIgnoreCase(method)){if(player.length()==0){json(socket,403,new JSONObject().put("error","convite inválido"));return;}Map<String,String> form=query(body);String action=form.get("action");if(action==null||action.trim().isEmpty()){json(socket,400,new JSONObject().put("error","ação vazia"));return;}db.addPartyAction(player.optLong("character_id"),player.optString("character_name"),limit(action.trim(),1600),"mesa_local");touch(player);json(socket,200,new JSONObject().put("ok",true).put("message","Ação enviada ao Mestre."));return;}json(socket,404,new JSONObject().put("error","rota inexistente"));}catch(Exception e){try{json(socket,500,new JSONObject().put("error","falha local"));}catch(Exception ignored){AppLog.ignored("LocalTableServer","Falha tolerada na camada 6.0.",ignored);}}finally{try{socket.close();}catch(Exception ignored){AppLog.ignored("LocalTableServer","Falha tolerada na camada 6.0.",ignored);}}}
    private JSONObject playerState(JSONObject p){JSONObject o=new JSONObject();try{long cid=p.optLong("character_id");syncPrivateKnowledge(cid,p.optString("character_name"));JSONObject hero=db.queryOne("SELECT id,name,species,class_name,level,hp,max_hp,ac,equipment,spells,proficiencies,token_uri,sheet_json FROM characters WHERE world_profile=? AND id=?",new String[]{db.getActiveMapProfile(),String.valueOf(cid)});o.put("hero",hero).put("scene",sharedScene()).put("combat",ownCombat(cid,p.optString("character_name"))).put("rumors",new RumorNetworkEngine(db).knownByHero(cid,40)).put("secrets",new JSONArray(db.queryList("SELECT title,body,created_at FROM local_table_secrets WHERE world_profile=? AND character_id=? AND active=1 ORDER BY created_at DESC LIMIT 50",new String[]{db.getActiveMapProfile(),String.valueOf(cid)}))).put("queued_actions",new JSONArray(db.queryList("SELECT action_text,status,created_at FROM party_action_queue WHERE world_profile=? AND character_id=? ORDER BY created_at DESC LIMIT 10",new String[]{db.getActiveMapProfile(),String.valueOf(cid)}))).put("server_time",System.currentTimeMillis());}catch(Exception ignored){AppLog.ignored("LocalTableServer","Falha tolerada na camada 6.0.",ignored);}return o;}

    public synchronized boolean addPrivateSecret(long characterId,String title,String body){try{String clean=body==null?"":body.trim();if(characterId<=0||clean.isEmpty())return false;ContentValues v=new ContentValues();v.put("world_profile",db.getActiveMapProfile());v.put("character_id",characterId);v.put("title",title==null||title.trim().isEmpty()?"Informação privada":title.trim());v.put("body",limit(clean,4000));v.put("event_key","manual-secret:"+UUID.randomUUID().toString());v.put("active",1);v.put("created_at",System.currentTimeMillis());return db.getWritableDatabase().insert("local_table_secrets",null,v)>0;}catch(Exception e){AppLog.w("LocalTable","Falha ao registrar segredo privado.",e);return false;}}
    private void syncPrivateKnowledge(long characterId,String characterName){try{String id=String.valueOf(characterId),name=characterName==null?"":characterName.trim();for(JSONObject fact:db.listKnowledgeFacts(250)){String visibility=fact.optString("visibility","").toLowerCase(Locale.ROOT);String known=fact.optString("known_by_json","[]");boolean privateFlag=visibility.matches(".*(privad|individual|segredo|secret|hero).*"),matches=false;try{JSONArray a=new JSONArray(known);for(int i=0;i<a.length();i++){Object raw=a.opt(i);if(raw instanceof JSONObject){JSONObject x=(JSONObject)raw;String xid=x.optString("id",x.optString("character_id")),xn=x.optString("name",x.optString("character_name"));if(id.equals(xid)||(!name.isEmpty()&&name.equalsIgnoreCase(xn)))matches=true;}else{String x=String.valueOf(raw);if(id.equals(x)||(!name.isEmpty()&&name.equalsIgnoreCase(x)))matches=true;}}}catch(Exception ignored){matches=known.contains("\""+id+"\"")||(!name.isEmpty()&&known.toLowerCase(Locale.ROOT).contains(name.toLowerCase(Locale.ROOT)));}if(!matches||(!privateFlag&&"grupo".equals(visibility)))continue;String key=fact.optString("fact_key").trim();if(key.isEmpty())key="knowledge:"+fact.optLong("id");if(db.queryOne("SELECT id FROM local_table_secrets WHERE world_profile=? AND character_id=? AND event_key=?",new String[]{db.getActiveMapProfile(),id,key}).length()>0)continue;ContentValues v=new ContentValues();v.put("world_profile",db.getActiveMapProfile());v.put("character_id",characterId);v.put("title",fact.optString("subject","Informação privada"));v.put("body",limit(fact.optString("content"),4000));v.put("event_key",key);v.put("active",1);v.put("created_at",fact.optLong("created_at",System.currentTimeMillis()));db.getWritableDatabase().insert("local_table_secrets",null,v);}}catch(Exception e){AppLog.w("LocalTable","Falha ao projetar conhecimento privado do herói.",e);}}
    private JSONObject sharedScene(){JSONObject s=db.getSceneState(),o=new JSONObject();try{o.put("day_number",s.optInt("day_number",1)).put("location",s.optString("location")).put("time_of_day",s.optString("time_of_day")).put("weather",s.optString("weather")).put("lighting",s.optString("lighting")).put("objective",s.optString("objective")).put("story",db.getStoryState().optString("last_narration")).put("options_json",db.getStoryState().optString("options_json","[]"));}catch(Exception ignored){AppLog.ignored("LocalTableServer","Falha tolerada na camada 6.0.",ignored);}return o;}
    private JSONObject ownCombat(long cid,String name){return db.queryOne("SELECT c.id,c.name,c.initiative,c.hp,c.max_hp,c.temp_hp,c.ac,c.conditions,c.active_turn,t.x,t.y FROM combatants c LEFT JOIN tactical_tokens t ON t.combatant_id=c.id AND t.world_profile=c.world_profile WHERE c.world_profile=? AND ((c.source_kind='character' AND c.source_id=?) OR lower(c.name)=lower(?)) LIMIT 1",new String[]{db.getActiveMapProfile(),String.valueOf(cid),name});}
    private JSONObject player(String token){if(token==null||token.length()<8)return new JSONObject();return db.queryOne("SELECT * FROM local_table_players WHERE world_profile=? AND session_code=? AND join_token=? AND active=1",new String[]{db.getActiveMapProfile(),sessionCode,token});}
    private void touch(JSONObject p){ContentValues v=new ContentValues();v.put("last_seen",System.currentTimeMillis());db.getWritableDatabase().update("local_table_players",v,"id=?",new String[]{String.valueOf(p.optLong("id"))});}
    private static void json(Socket s,int code,JSONObject o)throws Exception{reply(s,code,"application/json; charset=utf-8",o.toString());}
    private static void reply(Socket s,int code,String type,String body)throws Exception{byte[] data=body.getBytes(StandardCharsets.UTF_8);OutputStream out=s.getOutputStream();String h="HTTP/1.1 "+code+" "+(code==200?"OK":"ERROR")+"\r\nContent-Type: "+type+"\r\nContent-Length: "+data.length+"\r\nCache-Control: no-store\r\nConnection: close\r\nX-Content-Type-Options: nosniff\r\n\r\n";out.write(h.getBytes(StandardCharsets.UTF_8));out.write(data);out.flush();}
    private static Map<String,String> query(String raw)throws Exception{HashMap<String,String> m=new HashMap<String,String>();if(raw==null)return m;for(String part:raw.split("&")){int i=part.indexOf('=');String k=i<0?part:part.substring(0,i),v=i<0?"":part.substring(i+1);m.put(URLDecoder.decode(k,"UTF-8"),URLDecoder.decode(v,"UTF-8"));}return m;}
    private static String loginPage(){return "<!doctype html><meta charset='utf-8'><meta name='viewport' content='width=device-width'><style>body{background:#071a12;color:#eee;font-family:sans-serif;padding:24px}h1{color:#d8bd61}</style><h1>Braseiro — Mesa Local</h1><p>Este convite não é válido. Abra o endereço individual mostrado no aparelho do Mestre.</p>";}
    private static String playerPage(JSONObject p,String token){String name=escape(p.optString("character_name"));String t=escape(token);return "<!doctype html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><style>body{margin:0;background:#071a12;color:#f2f0e7;font-family:system-ui;padding:16px}.card{background:#113323;border:1px solid #6e815f;border-radius:14px;padding:14px;margin:10px 0}h1,h2{color:#d8bd61}textarea{width:100%;min-height:110px;background:#0b2619;color:#fff;border:1px solid #6e815f;border-radius:10px;padding:10px;box-sizing:border-box}button{width:100%;padding:14px;background:#d8bd61;color:#111;border:0;border-radius:10px;font-weight:bold}</style></head><body><h1>"+name+"</h1><div id='state'>Conectando…</div><div class='card'><h2>Sua ação</h2><textarea id='a' placeholder='Descreva o que seu herói faz ou diz'></textarea><button onclick='send()'>ENVIAR AO MESTRE</button><p id='msg'></p></div><script>const token='"+t+"';function esc(x){return String(x??'').replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]));}async function load(){let r=await fetch('/state?token='+encodeURIComponent(token));let s=await r.json();let h=s.hero||{},sc=s.scene||{},c=s.combat||{};document.getElementById('state').innerHTML=`<div class=card><h2>${esc(h.name)}</h2><b>${esc(h.species)} • ${esc(h.class_name)} ${h.level||''}</b><p>PV ${h.hp||0}/${h.max_hp||0} • CA ${h.ac||0}</p></div><div class=card><h2>${esc(sc.location||'Cena')}</h2><p>Dia ${sc.day_number||1} • ${esc(sc.time_of_day||'')} • ${esc(sc.weather||'')}</p><p>${esc(sc.objective||'')}</p></div>${c.name?`<div class=card><h2>Combate</h2><p>Iniciativa ${c.initiative||0} • PV ${c.hp||0}/${c.max_hp||0} • ${esc(c.conditions||'')}</p></div>`:''}<div class=card><h2>Rumores que você conhece</h2>${(s.rumors||[]).map(x=>`<p>• ${esc(x.statement)}</p>`).join('')||'<p>Nenhum.</p>'}</div><div class=card><h2>Informações privadas</h2>${(s.secrets||[]).map(x=>`<p><b>${esc(x.title)}</b><br>${esc(x.body)}</p>`).join('')||'<p>Nenhuma.</p>'}</div>`;}async function send(){let a=document.getElementById('a').value.trim();if(!a)return;let r=await fetch('/action?token='+encodeURIComponent(token),{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:'action='+encodeURIComponent(a)});let j=await r.json();document.getElementById('msg').textContent=j.message||j.error||'';if(j.ok)document.getElementById('a').value='';}load();setInterval(load,5000);</script></body></html>";}
    private static String localAddress(){try{Enumeration<NetworkInterface> ifs=NetworkInterface.getNetworkInterfaces();while(ifs.hasMoreElements()){NetworkInterface ni=ifs.nextElement();if(!ni.isUp()||ni.isLoopback())continue;Enumeration<InetAddress> as=ni.getInetAddresses();while(as.hasMoreElements()){InetAddress a=as.nextElement();if(a instanceof Inet4Address&&!a.isLoopbackAddress()&&a.isSiteLocalAddress())return a.getHostAddress();}}}catch(Exception ignored){AppLog.ignored("LocalTableServer","Falha tolerada na camada 6.0.",ignored);}return "127.0.0.1";}
    private static String randomToken(){return UUID.randomUUID().toString().replace("-","");}
    private static String limit(String s,int n){return s.length()<=n?s:s.substring(0,n);}
    private static String escape(String s){return (s==null?"":s).replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("'","&#39;").replace("\"","&quot;");}
}
